metadata.er-schema:
{
  "title": "looply · Market 市场主数据实体关系图",
  "version": "v1.0 · 2026-04-22",
  "tables": [
    {
      "name": "country",
      "comment": "国家/地区",
      "columns": [
        {
          "name": "country_code",
          "comment": "国家代码（如US/FR/DE）",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "country_name",
          "comment": "国家名称（英文）",
          "constraint": ""
        },
        {
          "name": "country_name_local",
          "comment": "本地语言名称",
          "constraint": ""
        },
        {
          "name": "dial_code",
          "comment": "电话区号（如+1/+33）",
          "constraint": ""
        },
        {
          "name": "default_currency_code",
          "comment": "法定货币",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "default_language_code",
          "comment": "主要语言",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "status",
          "comment": "状态",
          "constraint": ""
        }
      ],
      "note": "ISO 3166-1 alpha-2 作主键，全局唯一，多模块共用"
    },
    {
      "name": "currency",
      "comment": "货币",
      "columns": [
        {
          "name": "currency_code",
          "comment": "货币代码（如USD/EUR/GBP）",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "currency_name",
          "comment": "货币名称（英文）",
          "constraint": ""
        },
        {
          "name": "currency_symbol",
          "comment": "符号（如$/€/£）",
          "constraint": ""
        },
        {
          "name": "decimal_places",
          "comment": "小数位数",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态",
          "constraint": ""
        }
      ],
      "note": "ISO 4217 作主键，decimal_places 影响价格计算（JPY=0, USD=2, KWD=3）"
    },
    {
      "name": "language",
      "comment": "语言",
      "columns": [
        {
          "name": "language_code",
          "comment": "语言代码（如en-US/fr-FR）",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "language_name",
          "comment": "语言名称（英文）",
          "constraint": ""
        },
        {
          "name": "native_name",
          "comment": "本地名称（如Español）",
          "constraint": ""
        },
        {
          "name": "text_direction",
          "comment": "文字方向（ltr/rtl）",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态",
          "constraint": ""
        }
      ],
      "note": "IETF BCP 47 作主键（如en-US/es-US/fr-FR），区分地区差异"
    },
    {
      "name": "market",
      "comment": "市场",
      "columns": [
        {
          "name": "market_id",
          "comment": "市场ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "market_code",
          "comment": "市场编码（如US/EU/LATAM）",
          "constraint": "UNIQUE"
        },
        {
          "name": "market_name",
          "comment": "市场名称",
          "constraint": ""
        },
        {
          "name": "default_currency_code",
          "comment": "默认货币",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "default_language_code",
          "comment": "默认语言",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "timezone",
          "comment": "主时区",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态（活跃/停用）",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "一个Market可含多个国家，Channel归属Market"
    },
    {
      "name": "market_country",
      "comment": "市场-国家映射",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "market_id",
          "comment": "市场",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "country_code",
          "comment": "国家代码",
          "constraint": "FOREIGN KEY, UNIQUE"
        },
        {
          "name": "sort_order",
          "comment": "排序",
          "constraint": ""
        }
      ],
      "note": "country_code UNIQUE：一个国家只能归属一个Market"
    },
    {
      "name": "market_language",
      "comment": "市场-语言映射",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "market_id",
          "comment": "市场",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "language_code",
          "comment": "语言代码",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "is_default",
          "comment": "是否默认语言",
          "constraint": ""
        },
        {
          "name": "fallback_language_code",
          "comment": "回退语言",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "sort_order",
          "comment": "排序",
          "constraint": ""
        }
      ],
      "note": "fallback_language_code：翻译缺失时回退语言"
    },
    {
      "name": "market_currency",
      "comment": "市场-货币映射",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "market_id",
          "comment": "市场",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "currency_code",
          "comment": "货币代码",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "is_default",
          "comment": "是否默认货币",
          "constraint": ""
        },
        {
          "name": "exchange_rate",
          "comment": "汇率",
          "constraint": ""
        },
        {
          "name": "rate_updated_at",
          "comment": "汇率更新时间",
          "constraint": ""
        },
        {
          "name": "rounding_rule",
          "comment": "价格取整规则（none/up/down/nearest）",
          "constraint": ""
        }
      ],
      "note": "exchange_rate：相对基准货币的汇率"
    },
    {
      "name": "market_domain",
      "comment": "市场域名配置",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "market_id",
          "comment": "市场",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "domain_type",
          "comment": "域名类型（primary/subfolder/subdomain/ccTLD）",
          "constraint": ""
        },
        {
          "name": "domain_value",
          "comment": "域名值",
          "constraint": ""
        },
        {
          "name": "language_code",
          "comment": "对应语言",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "is_default",
          "comment": "是否默认域名",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态",
          "constraint": ""
        }
      ],
      "note": "支持多种域名策略：主域名/子路径/子域名/国家域名"
    },
    {
      "name": "translation",
      "comment": "内容翻译",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "entity_type",
          "comment": "实体类型（如spu/brand/category）",
          "constraint": ""
        },
        {
          "name": "entity_id",
          "comment": "实体ID",
          "constraint": ""
        },
        {
          "name": "field_name",
          "comment": "字段名（如name/description）",
          "constraint": ""
        },
        {
          "name": "language_code",
          "comment": "目标语言",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "content",
          "comment": "翻译内容",
          "constraint": ""
        },
        {
          "name": "source",
          "comment": "翻译来源（人工/机器/第三方）",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态（草稿/已发布）",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "集中式EAV模式：统一翻译工作流 + 语言回退逻辑只写一次"
    }
  ],
  "relations": [
    {
      "from": "country",
      "to": "currency",
      "type": "N:1",
      "label": "法定货币",
      "color": "#4A90D9",
      "penwidth": 1.4
    },
    {
      "from": "country",
      "to": "language",
      "type": "N:1",
      "label": "主要语言",
      "color": "#4A90D9",
      "penwidth": 1.4
    },
    {
      "from": "market",
      "to": "currency",
      "type": "N:1",
      "label": "默认货币",
      "color": "#E8833A",
      "penwidth": 1.4
    },
    {
      "from": "market",
      "to": "language",
      "type": "N:1",
      "label": "默认语言",
      "color": "#E8833A",
      "penwidth": 1.4
    },
    {
      "from": "market_country",
      "to": "market",
      "type": "N:1",
      "label": "归属市场",
      "color": "#E8833A",
      "penwidth": 1.4
    },
    {
      "from": "market_country",
      "to": "country",
      "type": "N:1",
      "label": "国家",
      "color": "#E8833A"
    },
    {
      "from": "market_language",
      "to": "market",
      "type": "N:1",
      "label": "市场",
      "color": "#E8833A"
    },
    {
      "from": "market_language",
      "to": "language",
      "type": "N:1",
      "label": "语言",
      "color": "#E8833A"
    },
    {
      "from": "market_language",
      "to": "language",
      "type": "N:1",
      "label": "回退语言",
      "color": "#90A4AE",
      "style": "dashed"
    },
    {
      "from": "market_currency",
      "to": "market",
      "type": "N:1",
      "label": "市场",
      "color": "#E8833A"
    },
    {
      "from": "market_currency",
      "to": "currency",
      "type": "N:1",
      "label": "货币",
      "color": "#E8833A"
    },
    {
      "from": "market_domain",
      "to": "market",
      "type": "N:1",
      "label": "市场",
      "color": "#E8833A"
    },
    {
      "from": "market_domain",
      "to": "language",
      "type": "N:1",
      "label": "对应语言",
      "color": "#90A4AE",
      "style": "dashed"
    },
    {
      "from": "translation",
      "to": "language",
      "type": "N:1",
      "label": "目标语言",
      "color": "#7B1FA2",
      "penwidth": 1.4
    }
  ],
  "design_rules": {
    "market_definition": "Market = 销售区域配置单元，一个Market可包含多个国家（如欧盟市场），也可只含一个国家（如美国市场）。Channel归属Market，是Market的下层维度",
    "country_unique_rule": "market_country.country_code 加 UNIQUE 约束，确保一个国家只能归属一个Market，避免客户被多个Market同时服务",
    "language_fallback": "market_language.fallback_language_code 定义翻译缺失时的回退语言（如 es-US 缺失回退到 en-US），避免显示空白",
    "translation_eav": "translation 表采用集中式 EAV 模式（entity_type + entity_id + field_name），所有业务域的翻译内容统一存储。优势：统一翻译工作流、语言回退逻辑只写一次、翻译覆盖率一条SQL统计",
    "translation_unique": "UNIQUE(entity_type, entity_id, field_name, language_code)，同一实体同一字段同一语言只有一条翻译",
    "currency_exchange": "market_currency.exchange_rate 存相对基准货币的汇率，rounding_rule 控制价格取整策略（如 $9.99 vs $10.00）",
    "domain_strategy": "market_domain 支持四种域名策略：primary（主域名）、subfolder（如/fr）、subdomain（如fr.looply.com）、ccTLD（如looply.fr）",
    "reference_data_pk": "基础参考数据（country/currency/language）使用国际标准代码作主键（ISO 3166-1/ISO 4217/BCP 47），语义清晰，跨模块引用时可读性强",
    "cross_module_impact": "Market模块引入后，商品域channel表需新增market_id FK，用户表country_code应FK引用country表。所有业务域按多市场设计"
  }
}
